<script setup lang="ts">
import { useDemoStore, type Location } from '@/stores/demo'
const store = useDemoStore(); const route = useRoute()
const section = computed(() => route.path.split('/').pop())
const form = reactive({ ...store.data.settings }); const saved = ref(false)
const dirty = computed(() => section.value !== 'locations' && JSON.stringify(form) !== JSON.stringify(store.data.settings))
watch(form, () => { saved.value = false }, { deep: true })
const removing = ref<Location | null>(null)
const removeOpen = computed({ get: () => !!removing.value, set: value => { if (!value) removing.value = null } })
watch(section, () => { Object.assign(form, store.data.settings); saved.value = false })
function save() { Object.assign(store.data.settings, form); saved.value = true }
const locationOpen = ref(false); const location = reactive<Location>({ id: 0, name: '', address: '', city: '', postalCode: '', pickup: false })
function editLocation(item?: Location) { Object.assign(location, item ?? { id: 0, name: '', address: '', city: '', postalCode: '', pickup: false }); locationOpen.value = true }
function saveLocation() { const found = store.data.locations.find(item => item.id === location.id); if (found) Object.assign(found, location); else store.data.locations.push({ ...location, id: store.nextId(store.data.locations) }); locationOpen.value = false }
</script>
<template>
  <PageHeader title="Pengaturan toko" eyebrow="SETTINGS" description="Atur identitas toko, metode pembayaran, dan lokasi pengiriman." />
  <VTabs :model-value="section" class="mb-5"><VTab to="/settings/store" value="store">Identitas toko</VTab><VTab to="/settings/payments" value="payments">Pembayaran</VTab><VTab to="/settings/locations" value="locations">Lokasi toko</VTab></VTabs>
  <VAlert v-if="saved" type="info" variant="tonal" closable class="mb-5" @click:close="saved = false">Pengaturan berhasil disimpan.</VAlert>
  <form v-if="section !== 'locations'" @submit.prevent="save"><VCard :title="section === 'store' ? 'Identitas toko' : 'Metode pembayaran'"><VCardText class="form-stack">
    <template v-if="section === 'store'"><VRow><VCol cols="12" md="6"><VTextField v-model="form.name" label="Nama toko" required maxlength="80" /></VCol><VCol cols="12" md="6"><VTextField v-model="form.email" label="Email toko" type="email" required /></VCol><VCol cols="12" md="6"><VTextField v-model="form.phone" label="Nomor telepon toko" required /></VCol><VCol cols="12" md="6"><VTextField model-value="Indonesian Rupiah (IDR)" label="Mata uang" readonly /></VCol></VRow><VTextarea v-model="form.description" label="Deskripsi toko" rows="3" maxlength="500" /><p class="text-body-2 text-medium-emphasis">Nama dan deskripsi akan terlihat di katalog pelanggan.</p></template>
    <template v-else><VAlert type="info" variant="tonal">Pilih metode yang boleh digunakan saat checkout. Pengaturan ini untuk demo; tidak ada pembayaran sungguhan.</VAlert><VSwitch v-model="form.bankTransfer" label="Aktifkan transfer bank" /><VRow v-if="form.bankTransfer"><VCol cols="12" md="4"><VTextField v-model="form.bankName" label="Nama bank" required /></VCol><VCol cols="12" md="4"><VTextField v-model="form.accountName" label="Nama pemilik rekening" required /></VCol><VCol cols="12" md="4"><VTextField v-model="form.accountNumber" label="Nomor rekening contoh" required /></VCol></VRow><VDivider /><VSwitch v-model="form.cashOnDelivery" label="Aktifkan bayar di tempat (COD)" /><p class="text-body-2 text-medium-emphasis">Metode yang aktif muncul di checkout. Jika semuanya nonaktif, pelanggan tidak dapat membuat pesanan.</p></template>
  </VCardText><VCardActions class="pa-5"><VSpacer /><span v-if="dirty" class="text-body-2 text-medium-emphasis">Perubahan belum disimpan</span><VBtn type="submit" variant="flat" :disabled="!dirty" prepend-icon="ri-save-line">Simpan perubahan</VBtn></VCardActions></VCard></form>
  <template v-else><div class="d-flex justify-end mb-4"><VBtn prepend-icon="ri-add-line" @click="editLocation()">Tambah lokasi</VBtn></div><VRow><VCol v-for="item in store.data.locations" :key="item.id" cols="12" md="6"><VCard><VCardText class="form-stack"><div class="d-flex align-center gap-3"><VAvatar color="primary" variant="tonal" rounded><VIcon icon="ri-map-pin-line" /></VAvatar><h3 class="text-h6">{{ item.name }}</h3></div><p>{{ item.address }}<br>{{ item.city }}, {{ item.postalCode }}</p><VChip :color="item.pickup ? 'primary' : 'secondary'" size="small" class="align-self-start">{{ item.pickup ? 'Bisa diambil di toko' : 'Hanya pengiriman' }}</VChip><div class="d-flex gap-2"><VBtn variant="tonal" @click="editLocation(item)">Edit lokasi</VBtn><VBtn variant="text" color="error" :disabled="store.data.locations.length === 1" @click="removing = item">Hapus</VBtn></div></VCardText></VCard></VCol></VRow><p class="text-caption mt-4">Simpan minimal satu lokasi. Lokasi terakhir tidak bisa dihapus. Opsi pengambilan di toko adalah contoh konfigurasi; checkout memakai pengiriman standar.</p></template>
  <VDialog v-model="locationOpen" max-width="520" aria-label="Location editor"><VCard tag="form" :title="location.id ? 'Edit lokasi' : 'Tambah lokasi'" @submit.prevent="saveLocation"><VCardText class="form-stack"><VTextField v-model="location.name" label="Nama lokasi" required /><VTextField v-model="location.address" label="Alamat lengkap" required /><VTextField v-model="location.city" label="Kota" required /><VTextField v-model="location.postalCode" label="Kode pos" required /><VSwitch v-model="location.pickup" label="Aktifkan pengambilan di toko" /></VCardText><VCardActions class="pa-4"><VSpacer /><VBtn @click="locationOpen = false">Batal</VBtn><VBtn type="submit" variant="flat">Simpan lokasi</VBtn></VCardActions></VCard></VDialog>
  <UnsavedChangesGuard :dirty="dirty" />
  <VDialog v-model="removeOpen" max-width="460" aria-label="Hapus lokasi"><VCard title="Hapus lokasi toko?"><VCardText><strong>{{ removing?.name }}</strong> akan dihapus dari daftar lokasi.</VCardText><VCardActions class="pa-5"><VSpacer /><VBtn variant="outlined" @click="removing = null">Batal</VBtn><VBtn variant="flat" color="error" @click="store.data.locations = store.data.locations.filter(l => l.id !== removing?.id); removing = null">Hapus lokasi</VBtn></VCardActions></VCard></VDialog>
</template>
